#pragma once
#include "core/startup_display_contracts.hpp"
#include "core/campaign_node_completion.hpp"
#include "core/entrance_actor_entries.hpp"
#include "core/text_numeric_sprites.hpp"
namespace rolo {
enum class SceneStep{PrepareAttractText,ResetTextSprites,LoadTitle,ResetWordQueue,ResetByteQueue,ResetActors,ResetGraphics,SpawnAttract,SpawnEntrance,CopyParents,FadeIn,FadeBlack,Music,ParseText,FormatGameOver,Replay,DrainTransfers,BuildActive,ActorCallbacks,Animate,Render,AttractMovement,Elephant,Rabbit,Squirrel,Beaver,PlayerPresentation,LoadPalette,PreparePaletteRotation,EntrancePlanes,ResetForegroundRows,ResetBackgroundRows,ResetPlaneGlobals,ForegroundScroll,BackgroundScroll,ClearPlane,ClearRegion,InitializeMenu,ReplayMenu,UpdateMenu};
struct SceneControlState{TitleTextState text;std::uint32_t main_state{};std::uint16_t selector{},timer{},foreground_h{},foreground_v{},background_h{},background_v{},origin_x{},saved_x{},origin_y{},saved_y{},window_word{};std::uint8_t credits{},complete{},actor_gate{},busy{},last_input{},pressed{},menu_closing{},unlock{},campaign_a{},campaign_b{};std::array<std::uint8_t,80>flags{};std::array<std::uint8_t,16>actor_types{};CampaignResetState score;};
struct SceneControlServices:VideoSetupPorts{virtual void step(SceneStep,std::uint32_t=0,std::uint32_t=0)=0;virtual void wait_event()=0;};
inline void reset_scene_planes(SceneControlState&s,SceneControlServices&v){v.step(SceneStep::ResetForegroundRows);v.step(SceneStep::ResetBackgroundRows);v.step(SceneStep::ResetPlaneGlobals);v.control(0x9100);v.control(0x929c);configure_original_video(v);s.foreground_h=s.foreground_v=s.background_h=s.background_v=0;v.step(SceneStep::ForegroundScroll);v.step(SceneStep::BackgroundScroll);}
inline void initialize_attract_scene(SceneControlState&s,SceneControlServices&v){s.text.frame_hook=0x1522;reset_scene_planes(s,v);for(auto op:{SceneStep::PrepareAttractText,SceneStep::ResetActors,SceneStep::ResetGraphics,SceneStep::SpawnAttract,SceneStep::CopyParents})v.step(op);s.selector=65535;v.step(SceneStep::FadeIn);v.step(SceneStep::Music,(s.credits&128)?9:10,65535);}
inline void initialize_game_over_scene(SceneControlState&s,SceneControlServices&v){s.text.frame_hook=0x15aa;v.step(SceneStep::FormatGameOver);v.step(SceneStep::ResetTextSprites);s.actor_gate=0;v.step(SceneStep::ClearPlane);reset_scene_planes(s,v);s.text.plane=0xc000;s.text.active_text=0xffff9804;s.text.attributes=0x6000;s.text.mode=s.text.delay=0;v.step(SceneStep::ParseText);v.step(SceneStep::Music,21,0);s.selector=65535;v.step(SceneStep::FadeIn);}
inline void initialize_entrance_scene(SceneControlState&s,SceneControlServices&v){s.text.frame_hook=0x165e;for(auto op:{SceneStep::ResetTextSprites,SceneStep::ResetWordQueue,SceneStep::ResetByteQueue,SceneStep::ClearPlane})v.step(op);reset_scene_planes(s,v);for(auto op:{SceneStep::ClearRegion,SceneStep::LoadTitle,SceneStep::ResetActors,SceneStep::ResetGraphics,SceneStep::SpawnEntrance,SceneStep::CopyParents})v.step(op);s.selector=65535;v.step(SceneStep::FadeIn);s.timer=850;v.step(SceneStep::Music,2,65535);}
inline void wait_scene_busy(SceneControlState&s,SceneControlServices&v){while(s.busy)v.wait_event();}
inline void step_attract_scene(SceneControlState&s,SceneControlServices&v){if(s.text.frame_hook!=0x1522)initialize_attract_scene(s,v);for(auto op:{SceneStep::Replay,SceneStep::DrainTransfers,SceneStep::BuildActive,SceneStep::ActorCallbacks,SceneStep::Animate,SceneStep::Render,SceneStep::AttractMovement})v.step(op);}
inline void step_game_over_scene(SceneControlState&s,SceneControlServices&v){if(s.text.frame_hook!=0x15aa)initialize_game_over_scene(s,v);v.step(SceneStep::ParseText);if(!s.busy)return;wait_scene_busy(s,v);v.step(SceneStep::FadeBlack);if(!s.complete)s.main_state=0x1522;else{s.complete=0;s.main_state=0x165e;}}
inline void step_entrance_fade(SceneControlState&s,SceneControlServices&v){if(s.timer&32768)return;if(s.timer){s.timer=std::uint16_t(s.timer-1);if(!s.timer){s.selector=65533;v.step(SceneStep::LoadPalette);v.step(SceneStep::PreparePaletteRotation);v.step(SceneStep::EntrancePlanes);}return;}s.timer=65535;s.selector=65532;v.step(SceneStep::FadeIn);s.main_state=0x171c;}
inline void scene_start_cheat(SceneControlState&s){if(s.last_input==101&&s.pressed)s.main_state=0x19ba;}
inline void step_entrance_scene(SceneControlState&s,SceneControlServices&v){if(s.text.frame_hook!=0x165e)initialize_entrance_scene(s,v);if(s.busy){wait_scene_busy(s,v);return;}scene_start_cheat(s);for(auto op:{SceneStep::Replay,SceneStep::DrainTransfers,SceneStep::BuildActive,SceneStep::Elephant,SceneStep::Rabbit,SceneStep::Squirrel,SceneStep::Beaver,SceneStep::PlayerPresentation,SceneStep::Animate,SceneStep::Render})v.step(op);step_entrance_fade(s,v);}
inline void step_title_text_scene(SceneControlState&s,SceneControlServices&v){if(s.text.frame_hook!=0x171c)initialize_title_text(s.text);if(s.busy){wait_scene_busy(s,v);return;}scene_start_cheat(s);v.step(SceneStep::ParseText);}
inline void initialize_new_campaign(SceneControlState&s){s.credits=4;reset_campaign_flags(s.flags,s.unlock);initialize_actor_type_gates(s.actor_types);s.origin_x=s.saved_x=280;s.origin_y=s.saved_y=472;reset_campaign_score(s.score);s.main_state=0x1a6e;s.campaign_a=s.campaign_b=255;}
inline void step_menu_scene(SceneControlState&s,SceneControlServices&v){if(s.text.frame_hook!=0x1e20)v.step(SceneStep::InitializeMenu);v.step(SceneStep::ReplayMenu);if(!s.menu_closing){v.step(SceneStep::UpdateMenu);return;}auto slide=std::uint8_t(s.window_word);if(slide){--slide;s.window_word=std::uint16_t((s.window_word&0xff00)|slide);v.control(s.window_word);}else s.main_state=0x1c6c;}
}

